const terminal=document.querySelector('#terminal-output');
function runCommand(value){const command=value.trim().toLowerCase();if(!command)return;if(command==='clear'){terminal.replaceChildren();return;}const line=document.createElement('p');line.className='muted';line.textContent='visitante ~ $ '+value.slice(0,150);const answer=document.createElement('p');answer.textContent=responses[command]||'Comando no reconocido. Escribe help para explorar las opciones.';terminal.append(line,answer);while(terminal.children.length>40)terminal.firstElementChild.remove();terminal.scrollTop=terminal.scrollHeight;}
document.querySelector('#terminal-form').addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#command');runCommand(input.value);input.value='';});document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>runCommand(b.dataset.command)));
const pipelineButton=document.querySelector('#pipeline-run');let pipelineTimers=[];pipelineButton.addEventListener('click',()=>{pipelineTimers.forEach(clearTimeout);const steps=[...document.querySelectorAll('#pipeline-stages li')];steps.forEach(s=>s.classList.remove('active'));pipelineButton.disabled=true;const messages=['01 / LA INTERFAZ ENVÍA LA SOLICITUD','02 / LA API VALIDA Y PROCESA','03 / LA BASE DE DATOS DEVUELVE EL RESULTADO','04 / LA INTERFAZ PRESENTA LA RESPUESTA'];steps.forEach((step,i)=>pipelineTimers.push(setTimeout(()=>{step.classList.add('active');document.querySelector('#pipeline-status').textContent=messages[i];},i*700)));pipelineTimers.push(setTimeout(()=>{document.querySelector('#pipeline-status').textContent='200 OK / RECORRIDO COMPLETO · SIMULACIÓN LOCAL';pipelineButton.disabled=false;},2900));});
