const canvas=document.querySelector('#system'),ctx=canvas.getContext('2d'),motionQuery=matchMedia('(prefers-reduced-motion: reduce)');let paused=motionQuery.matches,frame=0,width=0,height=0,angle=.2,pointerX=0,pointerY=0;const points=Array.from({length:210},(_,i)=>{const y=1-2*(i+.5)/210,r=Math.sqrt(1-y*y),phi=i*Math.PI*(3-Math.sqrt(5));return{x:Math.cos(phi)*r,y,z:Math.sin(phi)*r};});
function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(paused)draw();}
function draw(){if(!width||!height)return;ctx.clearRect(0,0,width,height);const radius=Math.min(width,height)*.345,cx=width*.52,cy=height*.49,rot=angle+pointerX*.22,tilt=.3+pointerY*.12;const projected=points.map(p=>{const x=p.x*Math.cos(rot)+p.z*Math.sin(rot),z=-p.x*Math.sin(rot)+p.z*Math.cos(rot);const y=p.y*Math.cos(tilt)-z*Math.sin(tilt),zz=p.y*Math.sin(tilt)+z*Math.cos(tilt);return{x:cx+x*radius,y:cy+y*radius,z:zz};});ctx.save();ctx.translate(cx,cy);ctx.rotate(-.38);ctx.strokeStyle='#708c4340';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,0,radius*1.32,radius*.39,0,0,Math.PI*2);ctx.stroke();ctx.setLineDash([3,6]);ctx.beginPath();ctx.ellipse(0,0,radius*1.49,radius*.55,.6,0,Math.PI*2);ctx.stroke();ctx.restore();for(let i=0;i<projected.length;i++){const a=projected[i];for(let j=i+1;j<projected.length;j++){const b=projected[j];const distance=Math.hypot(points[i].x-points[j].x,points[i].y-points[j].y,points[i].z-points[j].z);if(distance<.28){ctx.strokeStyle=`rgba(70,95,43,${.065+(a.z+b.z+2)*.065})`;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}}projected.sort((a,b)=>a.z-b.z).forEach((p,i)=>{const depth=(p.z+1)/2;ctx.fillStyle=i%19===0?'#8caf28':`rgba(48,72,28,${.22+depth*.72})`;ctx.beginPath();ctx.arc(p.x,p.y,1+depth*1.8,0,Math.PI*2);ctx.fill();});ctx.fillStyle='#23371c';ctx.font='500 '+Math.round(radius*.4)+'px "Space Grotesk", sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('ih',cx,cy);ctx.font='9px monospace';ctx.fillStyle='#526c3d';ctx.fillText('CONNECTED BY CURIOSITY',cx,cy+radius*.31);}
let previous=0;function animate(time){if(paused||document.hidden){frame=0;return;}if(time-previous>28){angle+=.0028;draw();previous=time;}frame=requestAnimationFrame(animate);}function syncAnimation(){cancelAnimationFrame(frame);frame=0;const b=document.querySelector('#orbit-toggle');b.setAttribute('aria-pressed',String(paused));b.textContent=paused?'Activar movimiento ↻':'Pausar movimiento Ⅱ';draw();if(!paused&&!document.hidden)frame=requestAnimationFrame(animate);}document.querySelector('#orbit-toggle').addEventListener('click',()=>{paused=!paused;syncAnimation();});motionQuery.addEventListener('change',e=>{paused=e.matches;syncAnimation();});canvas.addEventListener('pointermove',e=>{if(paused)return;const r=canvas.getBoundingClientRect();pointerX=(e.clientX-r.left)/r.width-.5;pointerY=(e.clientY-r.top)/r.height-.5;});canvas.addEventListener('pointerleave',()=>{pointerX=0;pointerY=0;});document.addEventListener('visibilitychange',syncAnimation);new ResizeObserver(resize).observe(canvas);resize();syncAnimation();
